// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITetherToken {
    function issue(uint amount) external;
    function balanceOf(address who) external view returns (uint);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use storage manipulation in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        // Step 1: Become the owner by overwriting storage slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Verify we're now the owner by checking we can call an owner-only function
        // We'll just try to mint tokens

        // Step 3: Mint tokens to ourselves (owner)
        // USDT has 6 decimals, so 1,000,000 USDT = 1_000_000 * 1e6
        uint256 mintAmount = 1_000_000 * 10**6;

        // Create interface for TetherToken
        ITetherToken target = ITetherToken(TARGET);
        target.issue(mintAmount);

        // Step 4: Check our balance increased
        uint256 attackerBalance = target.balanceOf(attacker);
        console.log("Attacker balance after exploit:", attackerBalance);
        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
